pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address sender, uint256 initialBalance, uint256 collectAmount) public {
        vm.assume(sender != address(0));
        vm.assume(initialBalance >= 1 ether);
        vm.assume(collectAmount <= initialBalance && collectAmount < type(uint256).max - 1 ether);

        // Fund sender with initialBalance
        vm.deal(sender, initialBalance);

        // Call Put for the first time
        vm.prank(sender);
        c.Put{value: initialBalance}(0);

        // Get balance before Collect
        (uint256 unlockTimeBefore, uint256 balanceBefore) = c.Acc(sender);

        // Call Collect
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, collectAmount));

        // Get balance after Collect
        (uint256 unlockTimeAfter, uint256 balanceAfter) = c.Acc(sender);

        // If Collect reverted, balance should stay same
        // If Collect succeeded, balance should decrease
        if (success) {
            assertTrue(balanceAfter == balanceBefore - collectAmount, "Balance should decrease by collect amount");
        } else {
            assertTrue(balanceAfter == balanceBefore, "Balance should not change when Collect reverts");
        }
    }
}

