contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, uint unlockTimeOffset, uint depositAmount, uint collectAmount) public {
        // deposit enough to meet MinSum (1 ether) and cover collectAmount
        vm.assume(unlockTimeOffset > 0 && unlockTimeOffset < 1000000);
        vm.assume(collectAmount >= 1 ether);
        vm.assume(collectAmount <= depositAmount);
        vm.assume(depositAmount >= collectAmount && depositAmount <= address(c).balance + 1e20);
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Put(block.timestamp + unlockTimeOffset);
        // Now collect should revert because unlockTime is in the future
