        (bool success,) = address(c).call{gas: 100000}(abi.encodeWithSignature("Collect(uint256)", collectAmount));
        // The reference contract: Collect reverts if block.timestamp <= unlockTime
        // The bug: unlockTime = block.timestamp, so the condition passes
        assertTrue(!success, "Collect should revert when unlockTime > block.timestamp");
    }
}

