pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address user, uint256 unlockTime, uint256 putValue, uint256 collectAmount) public {
        // Restrict inputs to avoid overflows and unrealistic values
        vm.assume(putValue <= 1e30);
        vm.assume(collectAmount <= 1e30);

        // Give user some ETH
        vm.deal(user, 1e31);

        // Perform Put
        vm.prank(user);
        c.Put{value: putValue}(unlockTime);

        // Record state before Collect
        uint256 balanceBefore = c.Acc(user).balance;

        // Try Collect
        vm.prank(user);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // Get state after Collect
        uint256 balanceAfter = c.Acc(user).balance;
        uint256 unlockAfter = c.Acc(user).unlockTime;

        // General rule: balance either stays same (if Collect reverted) or decreases by exactly collectAmount
        // Also, unlockTime must not be less than block.timestamp (original invariant)
        if (!success) {
            // Collect reverted - balance unchanged
            assertTrue(balanceAfter == balanceBefore, "Balance unchanged on revert");
        } else {
            // Collect succeeded - balance decreased by exactly collectAmount
            assertTrue(balanceAfter == balanceBefore - collectAmount, "Balance decreased by collectAmount");
        }
        // unlockTime should never be less than block.timestamp (original contract sets at least block.timestamp)
        assertTrue(unlockAfter >= block.timestamp, "unlockTime not decreased");
    }
}

