pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, uint unlockTime, uint deposit, uint withdraw) public {
        // Bound parameters to avoid overflow and ensure reasonable values
        unlockTime = bound(unlockTime, 0, block.timestamp + 1000);
        deposit = bound(deposit, 0, 100 ether);
        withdraw = bound(withdraw, 0, 100 ether);

        // Ensure caller has enough ether
        vm.deal(caller, deposit);

        // Deposit: caller puts ether and sets unlockTime
        vm.prank(caller);
        c.Put{value: deposit}(unlockTime);

        // Record balance before Collect
        (uint unlockBefore, uint balanceBefore) = c.Acc(caller);

        // Call Collect
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, withdraw));

        (uint unlockAfter, uint balanceAfter) = c.Acc(caller);

        // Rule: if Collect succeeded, balance decreased exactly by withdraw; if it reverted, balance unchanged
        if (success) {
            assertTrue(balanceAfter == balanceBefore - withdraw, "Balance should decrease by withdraw");
        } else {
            assertTrue(balanceAfter == balanceBefore, "Balance should remain unchanged on revert");
        }
    }
}
